program.compute:
options=read('/input/options')
ids=[r['id'] for r in options]
result=[]
for i in range(len(ids)):
 for j in range(i+1,len(ids)):
  pair=[ids[i],ids[j]]
  if valid(pair):
   result=pair
   break
 if len(result)>0:
  break

program.effects:
if exists('/output/selection'):
 selection=read('/output/selection')
else:
 selection=result
 write('/output/selection',selection)
s=receipt('report')
if s=='success':
 pass
elif s=='unknown':
 q=status('report')
 if q=='not_sent':
  send('report','team',selection)
elif s=='unattempted':
 send('report','team',selection)
if exists('/tmp/cache'):
 delete('/tmp/cache')

